import { describe, expect, it } from "vitest";
import {
  BOJ_MEETING_SCHEDULE,
  FOMC_MEETING_SCHEDULE,
  type MeetingDateItem,
} from "../data/macroSchedule";

/**
 * The published decision dates (the second day of each meeting) of the
 * Bank of Japan and the FOMC, 2024 - 2027.
 *
 * Sources:
 * - FOMC: https://www.federalreserve.gov/monetarypolicy/fomccalendars.htm
 * - BOJ:  https://www.boj.or.jp/en/mopo/mpmsche_minu/index.htm
 *
 * The schedules used to be generated by shifting the previous year by one day,
 * which produced eight wrong FOMC dates for 2026/2027 and four wrong BOJ
 * dates for 2025/2027: neither institution meets on a fixed weekday, so the
 * weekday pattern shifts every year. These tests pin the real dates.
 */
const OFFICIAL_BOJ_DECISION_DATES: ReadonlyArray<MeetingDateItem> = [
  // 2024
  { year: 2024, month: 1, day: 23 },
  { year: 2024, month: 3, day: 19 },
  { year: 2024, month: 4, day: 26 },
  { year: 2024, month: 6, day: 14 },
  { year: 2024, month: 7, day: 31 },
  { year: 2024, month: 9, day: 20 },
  { year: 2024, month: 10, day: 31 },
  { year: 2024, month: 12, day: 19 },
  // 2025
  { year: 2025, month: 1, day: 24 },
  { year: 2025, month: 3, day: 19 },
  { year: 2025, month: 5, day: 1 },
  { year: 2025, month: 6, day: 17 },
  { year: 2025, month: 7, day: 31 },
  { year: 2025, month: 9, day: 19 },
  { year: 2025, month: 10, day: 30 },
  { year: 2025, month: 12, day: 19 },
  // 2026
  { year: 2026, month: 1, day: 23 },
  { year: 2026, month: 3, day: 19 },
  { year: 2026, month: 4, day: 28 },
  { year: 2026, month: 6, day: 16 },
  { year: 2026, month: 7, day: 31 },
  { year: 2026, month: 9, day: 18 },
  { year: 2026, month: 10, day: 30 },
  { year: 2026, month: 12, day: 18 },
  // 2027
  { year: 2027, month: 1, day: 22 },
  { year: 2027, month: 3, day: 18 },
  { year: 2027, month: 4, day: 28 },
  { year: 2027, month: 6, day: 11 },
  { year: 2027, month: 7, day: 22 },
  { year: 2027, month: 9, day: 22 },
  { year: 2027, month: 10, day: 29 },
  { year: 2027, month: 12, day: 17 },
];

const OFFICIAL_FOMC_DECISION_DATES: ReadonlyArray<MeetingDateItem> = [
  // 2024
  { year: 2024, month: 1, day: 31 },
  { year: 2024, month: 3, day: 20 },
  { year: 2024, month: 5, day: 1 },
  { year: 2024, month: 6, day: 12 },
  { year: 2024, month: 7, day: 31 },
  { year: 2024, month: 9, day: 18 },
  { year: 2024, month: 11, day: 7 },
  { year: 2024, month: 12, day: 18 },
  // 2025
  { year: 2025, month: 1, day: 29 },
  { year: 2025, month: 3, day: 19 },
  { year: 2025, month: 5, day: 7 },
  { year: 2025, month: 6, day: 18 },
  { year: 2025, month: 7, day: 30 },
  { year: 2025, month: 9, day: 17 },
  { year: 2025, month: 10, day: 29 },
  { year: 2025, month: 12, day: 10 },
  // 2026
  { year: 2026, month: 1, day: 28 },
  { year: 2026, month: 3, day: 18 },
  { year: 2026, month: 4, day: 29 },
  { year: 2026, month: 6, day: 17 },
  { year: 2026, month: 7, day: 29 },
  { year: 2026, month: 9, day: 16 },
  { year: 2026, month: 10, day: 28 },
  { year: 2026, month: 12, day: 9 },
  // 2027
  { year: 2027, month: 1, day: 27 },
  { year: 2027, month: 3, day: 17 },
  { year: 2027, month: 4, day: 28 },
  { year: 2027, month: 6, day: 9 },
  { year: 2027, month: 7, day: 28 },
  { year: 2027, month: 9, day: 15 },
  { year: 2027, month: 10, day: 27 },
  { year: 2027, month: 12, day: 8 },
];

const format = (item: MeetingDateItem) =>
  `${item.year}-${String(item.month).padStart(2, "0")}-${String(item.day).padStart(2, "0")}`;

describe("macro schedules match the published calendars", () => {
  it("lists exactly the published BOJ decision dates for 2024-2027", () => {
    expect(BOJ_MEETING_SCHEDULE.map(format)).toEqual(
      OFFICIAL_BOJ_DECISION_DATES.map(format),
    );
  });

  it("lists exactly the published FOMC decision dates for 2024-2027", () => {
    expect(FOMC_MEETING_SCHEDULE.map(format)).toEqual(
      OFFICIAL_FOMC_DECISION_DATES.map(format),
    );
  });

  it("has eight meetings per year for both institutions", () => {
    for (const year of [2024, 2025, 2026, 2027]) {
      expect(BOJ_MEETING_SCHEDULE.filter((m) => m.year === year)).toHaveLength(8);
      expect(FOMC_MEETING_SCHEDULE.filter((m) => m.year === year)).toHaveLength(8);
    }
  });

  it("uses a real calendar date for every entry", () => {
    for (const schedule of [BOJ_MEETING_SCHEDULE, FOMC_MEETING_SCHEDULE]) {
      for (const item of schedule) {
        expect(item.month).toBeGreaterThanOrEqual(1);
        expect(item.month).toBeLessThanOrEqual(12);
        expect(item.day).toBeGreaterThanOrEqual(1);
        // A day that does not exist in that month (e.g. February 30) would
        // silently roll over into the next month when the Date is built.
        expect(item.day).toBeLessThanOrEqual(31);
        const date = new Date(item.year, item.month - 1, item.day);
        expect(date.getMonth()).toBe(item.month - 1);
        expect(date.getDate()).toBe(item.day);
      }
    }
  });

  it("keeps the schedules sorted by date", () => {
    for (const schedule of [BOJ_MEETING_SCHEDULE, FOMC_MEETING_SCHEDULE]) {
      const times = schedule.map((m) => new Date(m.year, m.month - 1, m.day).getTime());
      for (let i = 1; i < times.length; i += 1) {
        expect(times[i]).toBeGreaterThan(times[i - 1]);
      }
    }
  });
});
